<template><view class="page quiz-page"><view class="back" @tap="back">‹</view><view class="head"><text class="eyebrow">每日打卡</text><text class="title">每日答题</text><text class="subtitle">每天一道低碳知识题，答对获得积分</text></view><view v-if="question.title" class="quiz-card card"><text class="category">{{question.category}} · +{{question.points}} 积分</text><text class="question">{{question.title}}</text><view v-for="(option,index) in question.options" :key="option" :class="['option',{selected:selected===letter(index),correct:submitted&&letter(index)===result.answer,wrong:submitted&&selected===letter(index)&&!result.isCorrect}]" @tap="select(letter(index))"><text>{{option}}</text></view><view v-if="submitted" class="result"><text>{{result.isCorrect?'回答正确，获得 '+result.points+' 积分':'回答错误，正确答案是 '+result.answer}}</text><text class="analysis">{{result.analysis}}</text></view><view v-else class="primary-btn submit" @tap="submit">提交答案</view></view><view v-else class="empty card">正在加载今日题目…</view></view></template>
<script>
import { callCloud } from '../../common/cloud.js'
import { toast } from '../../common/mock.js'
export default { data(){return{question:{},selected:'',submitted:false,result:{}}},async onLoad(){try{const session=uni.getStorageSync('user_session')||{};const result=await callCloud('carbon-question-today',{userId:session.id});this.question=result.data||{};if(result.completed)this.submitted=true}catch(error){toast(error.message||'题目加载失败')}},methods:{letter(index){return String.fromCharCode(65+index)},select(value){if(!this.submitted)this.selected=value},async submit(){if(!this.selected)return toast('请选择答案');try{const session=uni.getStorageSync('user_session')||{};this.result=await callCloud('carbon-quiz-submit',{userId:session.id,questionId:this.question._id,answer:this.selected});this.submitted=true;if(this.result.points)uni.setStorageSync('user_points',Number(uni.getStorageSync('user_points')||0)+this.result.points)}catch(error){toast(error.message||'提交失败')}},back(){uni.navigateBack()}}}
</script>
<style lang="scss">@import '../../common/portal.scss';.quiz-page{padding-top:18rpx}.back{width:68rpx;height:68rpx;font-size:58rpx}.head{padding:20rpx 0 28rpx}.eyebrow{display:block;color:#398052;font-size:24rpx}.title{display:block;margin-top:10rpx;font-size:46rpx;font-weight:700}.subtitle{display:block;margin-top:10rpx;color:#7b8981;font-size:23rpx}.quiz-card{padding:30rpx}.category{color:#398052;font-size:23rpx}.question{display:block;margin:24rpx 0;color:#1c281f;font-size:32rpx;font-weight:700;line-height:1.5}.option{margin-top:16rpx;padding:22rpx;border:2rpx solid #e0e8e2;border-radius:18rpx;color:#53615f;font-size:25rpx}.option.selected{border-color:#398052;background:#e3f2e7}.option.correct{border-color:#398052;background:#d5f0dc}.option.wrong{border-color:#d46b6b;background:#fff0f0}.submit{margin-top:28rpx}.result{margin-top:24rpx;padding:20rpx;border-radius:18rpx;background:#e8f5eb;color:#2f7a4a;font-size:24rpx;line-height:1.6}.analysis{display:block;margin-top:10rpx;color:#65746b}.empty{margin-top:30rpx;padding:50rpx;text-align:center}</style>
